#!/usr/bin/env python3
"""Native relief geometry, source, collision and image checks through MCP; no window."""
import copy
import hashlib
import json
from pathlib import Path
from verify_lab import Client, ROOT
from open_earth_walk import init
from relief_compositions import documents, position, ZERO

OUT = ROOT / 'artifacts/relief-tools'
PREFIX = 'artifacts/relief-tools'
# Captured from the pre-Landform2 native binary, not regenerated by this verifier.
LEGACY_BASELINE = {
    'build_id': 'aarch64-apple-darwin|release|rustc 1.97.1 (8bab26f4f 2026-07-14)|84893626b0fb0d2e',
    'source_sha256': '9106311df29b2cfeb368708d96f74ccc5aad1c77fc973a70073614c8d89fa70e',
    'geometry_sha256': '6c20654b58e7fe2e449f5fd2976607f513ddf3461062f2b88fabbe915d07213b',
}


def digest(value):
    return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':')).encode()).hexdigest()


def probe_document():
    def row(at,scale,radial):
        return dict(at=at,scale=scale,offset=[0,0],radial_scales=radial)
    return dict(version=2,space_version=1,id='probe',revision=1,origin=ZERO,pieces=[{
        'id':'cliff','anchor':[0,0,0],'axis':[0,1,0],'profile_x':[1,0,0],
        'profile':[[-1,-1],[1,-1],[1,1],[-1,1]],'inner_scale':None,
        'sections':[row(0,4,[1]*4),row(4,3,[1,.8,1.1,.9]),
                    row(4,5,[1]*4),row(8,5,[.9,1.1,1.2,.8])]}])


def verify():
    OUT.mkdir(parents=True,exist_ok=True)
    recipe=json.loads((ROOT/'examples/relief-compositions.recipe.json').read_text())
    c=Client(ROOT/'target/release/ignis',log_path=OUT/'mcp.log')
    results=[]
    try:
        init(c);build=c.call('inspect')['build_id']
        schema=json.dumps(c.request('tools/list')['result'])
        assert 'radial_scales' in schema and 'set_domain' in schema
        old=c.call('load_landform',path='examples/landforms.ignis-landform')['document']
        compiled=c.call('query_landform',query={'kind':'compile','document':old})
        baseline=LEGACY_BASELINE
        assert compiled['source_sha256']==baseline['source_sha256']
        assert digest(compiled['geometry'])==baseline['geometry_sha256']
        c.call('save_landform',path=f'{PREFIX}/legacy.ignis-landform',document=old)
        assert (OUT/'legacy.ignis-landform').read_bytes()==(ROOT/'examples/landforms.ignis-landform').read_bytes()
        for family in recipe['families']:
            assert documents(recipe,family)==documents(recipe,family)
            for sphere in [False,True]:
                mode='sphere' if sphere else 'plane';name=f'{family}-{mode}'
                rocks,caps=documents(recipe,family,sphere)
                inspected=[]
                for label,doc in [('rock',rocks),('caps',caps)]:
                    if not doc['pieces']:continue
                    compiled=c.call('query_landform',query={'kind':'compile','document':doc})
                    assert all(p['closed_oriented'] and p['signed_volume_cubic_meters']>0 for p in compiled['parts'])
                    source=f'{PREFIX}/{name}-{label}.ignis-landform'
                    c.call('save_landform',path=source,document=doc)
                    assert c.call('load_landform',path=source)['document']==doc
                    inspected.append({'kind':label,'vertices':len(compiled['geometry']['positions']),
                        'triangles':len(compiled['geometry']['triangles']),
                        'rounding_meters':compiled['maximum_vertex_rounding_meters'],
                        'sampled_domain_error_meters':compiled.get('maximum_sampled_domain_error_meters'),
                        'source_sha256':compiled['source_sha256']})
                c.call('generate',recipe={'width':16,'depth':16,'seed':221,'obstacles':0})
                c.call('edit_scene',edits=[{'op':'remove','id':e['id']} for e in c.call('inspect')['scene']['entities']])
                before=c.call('inspect')['scene']
                publication=dict(document=rocks,asset='rocks',instance='rocks',frame_origin=rocks['origin'],
                                 color=[.43,.49,.55],shading='flat',collision=True)
                material=copy.deepcopy(json.loads((ROOT/'assets/materials/rock/fractured.ignis-material').read_text())['material'])
                material['procedural']['recipe']['tile_size']=[32,32]
                material['procedural']['recipe']['rock']['dark']=[.11,.14,.17]
                material['procedural']['recipe']['rock']['light']=[.4,.44,.47]
                publication['material']=material
                publication['color']=[.9,.95,1]
                c.call('publish_landform',publication=publication)
                after=c.call('inspect')['scene']
                c.call('undo');assert c.call('inspect')['scene']==before
                c.call('redo');assert c.call('inspect')['scene']==after
                bad=copy.deepcopy(publication);bad['document']['pieces'][-1]['sections'][-1]['radial_scales']=[-1]
                c.call('publish_landform',publication=bad,expected_error=True)
                assert c.call('inspect')['scene']==after
                if caps['pieces']:
                    c.call('publish_landform',publication=dict(document=caps,asset='caps',instance='caps',
                        frame_origin=rocks['origin'],color=[.3,.47,.24],shading='flat',collision=False))
                datum=rocks['origin']
                ground=dict(version=1,space_version=1,id='floor',revision=1,datum=datum,
                            base={'kind':'constant','height_meters':-12.03 if family=='towers' else -.03},operations=[])
                origin=copy.deepcopy(datum)
                origin['cell'][0]='-2';origin['offset'][0]=48
                origin['cell'][2]='-2';origin['offset'][2]=48
                c.call('publish_terrain',publication={'document':ground,'patch':{'origin':origin,'cells':[32,32],'spacing_meters':125},
                    'stride':1,'asset':'floor','instance':'floor','frame_origin':datum,'color':[.25,.36,.23],'collision':True})
                light=c.call('inspect')['scene']['light']
                light.update(direction=[.6,-1,-.4],ambient=.28,direct_color=[1,.9,.78],direct_intensity=1,
                             environment=None,atmosphere={'density':.0006,'reduce_details':False,
                             'color':[.48,.65,.8],'sun_color':[1,.9,.75],'sun_strength':.1},shadow=None)
                c.call('set_light',light=light)
                camera={'position':[190,130,220],'target':[0,28,0],'fov_degrees':52}
                if family=='towers':camera.update(position=[180,155,240],target=[0,45,0])
                if family=='massif':camera.update(position=[300,170,340],target=[0,65,0])
                c.call('set_camera',camera=camera)
                c.call('save_scene',path=f'{PREFIX}/{name}.scene.json')
                image=f'{PREFIX}/{name}.png'
                c.call('capture',path=image,width=1280,height=800)
                saved=(ROOT/image).read_bytes()
                c.call('load_scene',path=f'{PREFIX}/{name}.scene.json')
                c.call('capture',path=f'{PREFIX}/reloaded.png',width=1280,height=800)
                assert (OUT/'reloaded.png').read_bytes()==saved
                results.append({'family':family,'domain':mode,'parts':inspected,'image':image})
                print(json.dumps({'captured':name}),flush=True)
        # Query overhangs and derived metrics, then cross beneath the published roof.
        doc=probe_document()
        hits=c.call('query_landform',query={'kind':'raycast','document':doc,'rays':[
            {'origin':[4.3,20,0],'direction':[0,-1,0],'max_distance_meters':100}]})['hits'][0]
        assert len(hits)==2 and hits[0]['slope_degrees']<.001 and hits[1]['slope_degrees']>179
        c.call('generate',recipe={'width':20,'depth':20,'seed':221,'obstacles':0})
        scene=c.call('inspect')['scene'];player=next(e for e in scene['entities'] if e['id']=='player')
        edits=[{'op':'remove','id':e['id']} for e in scene['entities'] if e['id'] not in ['floor','player']]
        player.update(transform={'position':[4.6,.85,-1],'size':[.6,1.6,.6]},
            character_controller={'max_slope_degrees':45,'slide_slope_degrees':50,'offset':.01,'snap_distance':.2,'gravity':9.81})
        edits.append({'op':'upsert','entity':player});c.call('edit_scene',edits=edits)
        c.call('publish_landform',publication=dict(document=doc,asset='roof',instance='roof',frame_origin=ZERO,
            color=[.5,.5,.5],shading='flat',collision=True))
        c.call('step',ticks=60)
        start=c.call('inspect')['runtime_positions']['player']
        c.call('set_input',input={'x':0,'z':1});c.call('step',ticks=45)
        c.call('set_input',input={'x':0,'z':0});c.call('step',ticks=30)
        end=c.call('inspect')['runtime_positions']['player']
        assert end[2]>start[2]+1 and .7<end[1]<1.1,(start,end)
        c.call('save_replay',path=f'{PREFIX}/under-roof.replay.json')
        assert c.call('run_replay',path=f'{PREFIX}/under-roof.replay.json')['matched']
        report=dict(build_id=build,passed=True,native_window=False,legacy_baseline=baseline,
                    compositions=results,under_roof={'start':start,'end':end},
                    artistic_acceptance=False,planet_runtime_integration=False,fps_measured=False)
        (OUT/'verification.json').write_text(json.dumps(report,indent=2))
        print(json.dumps({'passed':True,'compositions':len(results),'build':build}),flush=True)
    finally:c.close()


if __name__=='__main__':verify()
